PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, profile_id TEXT NOT NULL, updated_at INTEGER NOT NULL, save_version INTEGER NOT NULL CHECK(save_version > 0), take_selection_version INTEGER NOT NULL CHECK(take_selection_version >= 0), audio_mix_version INTEGER NOT NULL CHECK(audio_mix_version >= 0), selected_audio_mix_id TEXT, payload TEXT NOT NULL);
CREATE TABLE project_refs(project_id TEXT NOT NULL REFERENCES projects(id), role TEXT NOT NULL, ordinal INTEGER NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, PRIMARY KEY(project_id,role,ordinal), FOREIGN KEY(target_kind,target_id) REFERENCES records(kind,id));
CREATE TABLE records(kind TEXT NOT NULL, id TEXT NOT NULL, project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT, natural_key TEXT, payload TEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE UNIQUE INDEX records_global_id ON records(id);
CREATE INDEX records_project_lookup ON records(project_id,kind,id);
CREATE TABLE assets(asset_kind TEXT NOT NULL DEFAULT 'asset' CHECK(asset_kind='asset'), asset_id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, mime TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>0), source_job_kind TEXT NOT NULL DEFAULT 'job' CHECK(source_job_kind='job'), source_job_id TEXT, FOREIGN KEY(asset_kind,asset_id) REFERENCES records(kind,id), FOREIGN KEY(source_job_kind,source_job_id) REFERENCES records(kind,id));
CREATE TABLE approvals(approval_kind TEXT NOT NULL DEFAULT 'approval' CHECK(approval_kind='approval'), approval_id TEXT PRIMARY KEY, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, target_record_kind TEXT NOT NULL, target_record_id TEXT NOT NULL, target_hash TEXT NOT NULL, decision TEXT NOT NULL, FOREIGN KEY(approval_kind,approval_id) REFERENCES records(kind,id), FOREIGN KEY(target_record_kind,target_record_id) REFERENCES records(kind,id), UNIQUE(target_kind,target_id,target_hash,decision));
CREATE TABLE takes(take_kind TEXT NOT NULL DEFAULT 'take' CHECK(take_kind='take'), take_id TEXT PRIMARY KEY, shot_kind TEXT NOT NULL DEFAULT 'shot' CHECK(shot_kind='shot'), shot_revision_id TEXT NOT NULL, anchor_kind TEXT NOT NULL DEFAULT 'anchor' CHECK(anchor_kind='anchor'), anchor_id TEXT NOT NULL, approval_kind TEXT NOT NULL DEFAULT 'approval' CHECK(approval_kind='approval'), approval_id TEXT NOT NULL, job_kind TEXT NOT NULL DEFAULT 'job' CHECK(job_kind='job'), job_id TEXT NOT NULL, asset_kind TEXT NOT NULL DEFAULT 'asset' CHECK(asset_kind='asset'), asset_id TEXT NOT NULL, inputs_hash TEXT NOT NULL, FOREIGN KEY(take_kind,take_id) REFERENCES records(kind,id), FOREIGN KEY(shot_kind,shot_revision_id) REFERENCES records(kind,id), FOREIGN KEY(anchor_kind,anchor_id) REFERENCES records(kind,id), FOREIGN KEY(approval_kind,approval_id) REFERENCES records(kind,id), FOREIGN KEY(job_kind,job_id) REFERENCES records(kind,id), FOREIGN KEY(asset_kind,asset_id) REFERENCES records(kind,id));
CREATE TABLE jobs(job_kind TEXT NOT NULL DEFAULT 'job' CHECK(job_kind='job'), job_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), idempotency_key TEXT NOT NULL, status TEXT NOT NULL, provider_ref TEXT UNIQUE, request_hash TEXT NOT NULL, FOREIGN KEY(job_kind,job_id) REFERENCES records(kind,id), UNIQUE(project_id,idempotency_key));
CREATE TABLE manifests(manifest_kind TEXT NOT NULL DEFAULT 'manifest' CHECK(manifest_kind='manifest'), manifest_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), inputs_hash TEXT NOT NULL, FOREIGN KEY(manifest_kind,manifest_id) REFERENCES records(kind,id), UNIQUE(project_id,inputs_hash));
CREATE TABLE audio_cues(mix_kind TEXT NOT NULL DEFAULT 'audioMix' CHECK(mix_kind='audioMix'), mix_id TEXT NOT NULL, ordinal INTEGER NOT NULL, asset_kind TEXT NOT NULL DEFAULT 'asset' CHECK(asset_kind='asset'), asset_id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(mix_id,ordinal), FOREIGN KEY(mix_kind,mix_id) REFERENCES records(kind,id), FOREIGN KEY(asset_kind,asset_id) REFERENCES records(kind,id));
CREATE UNIQUE INDEX records_job_idempotency ON records(project_id,natural_key) WHERE kind='job' AND natural_key IS NOT NULL;
CREATE UNIQUE INDEX records_global_natural_key ON records(kind,natural_key) WHERE project_id IS NULL AND natural_key IS NOT NULL;
CREATE TABLE record_refs(owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, role TEXT NOT NULL, ordinal INTEGER NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, PRIMARY KEY(owner_kind,owner_id,role,ordinal), FOREIGN KEY(owner_kind,owner_id) REFERENCES records(kind,id) ON DELETE RESTRICT, FOREIGN KEY(target_kind,target_id) REFERENCES records(kind,id) ON DELETE RESTRICT);
CREATE INDEX record_refs_target ON record_refs(target_kind,target_id);
CREATE TABLE take_selections(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, shot_id TEXT NOT NULL, take_kind TEXT NOT NULL DEFAULT 'take' CHECK(take_kind='take'), take_id TEXT, PRIMARY KEY(project_id,shot_id), FOREIGN KEY(take_kind,take_id) REFERENCES records(kind,id));
CREATE TABLE job_leases(job_kind TEXT NOT NULL DEFAULT 'job' CHECK(job_kind='job'), job_id TEXT PRIMARY KEY, lease_token TEXT NOT NULL, lease_until INTEGER NOT NULL, heartbeat_at INTEGER NOT NULL, FOREIGN KEY(job_kind,job_id) REFERENCES records(kind,id));
CREATE TABLE outbox(id TEXT PRIMARY KEY, job_kind TEXT NOT NULL DEFAULT 'job' CHECK(job_kind='job'), job_id TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, claimed_at INTEGER, claim_until INTEGER, claim_token TEXT, FOREIGN KEY(job_kind,job_id) REFERENCES records(kind,id));
CREATE INDEX outbox_claimable ON outbox(claim_until,created_at);
CREATE TABLE job_events(job_kind TEXT NOT NULL DEFAULT 'job' CHECK(job_kind='job'), job_id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence > 0), at INTEGER NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL, progress REAL, PRIMARY KEY(job_id,sequence), FOREIGN KEY(job_kind,job_id) REFERENCES records(kind,id));
CREATE TABLE legacy_imports(source_key TEXT PRIMARY KEY, source_sha256 TEXT NOT NULL, imported_at INTEGER NOT NULL, record_count INTEGER NOT NULL, report_json TEXT NOT NULL);
CREATE TABLE legacy_records(source_key TEXT NOT NULL, record_key TEXT NOT NULL, source_path TEXT NOT NULL, source_sha256 TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(source_key,record_key));
